const NEXUS_LOGO_WATERMARK = "data:image/png;base64,";
/* =========================================================
   NEXUS — report bridge
   Include on every TOOL page (after supabase-client.js and
   auth-guard.js). Gives each tool two capabilities:
     1) NexusBridge.saveReport(...)   -> writes an immutable
        row into `reports` (only admins can edit/delete later)
     2) NexusBridge.exportBrandedPDF(...) -> turns any HTML
        snapshot into an Omega-branded PDF the client can
        download, and stores a copy in Supabase Storage.
   Requires html2canvas + jsPDF (loaded via CDN in the tool page):
   <script src="https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js"></script>
   <script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>

   Why not html2pdf.js? Its automatic image-to-page scaling produced
   PDFs that were cropped on one side for our reports (the rendered
   canvas was wider than what its internal scale calculation expected).
   Driving html2canvas and jsPDF directly, and computing the page
   scaling ourselves from the ACTUAL captured canvas size, removes
   that guesswork entirely — the image is always scaled to exactly
   match the PDF page width, so nothing is ever cropped.
   ========================================================= */

const NexusBridge = (function(){
  const CAPTURE_SCALE = 2; // must match the `scale` option passed to html2canvas below

  async function currentProfile(){
    const { data: { session } } = await nexus.auth.getSession();
    if (!session) throw new Error('Not signed in');
    const { data: profile } = await nexus.from('profiles').select('*').eq('id', session.user.id).single();
    return profile;
  }

  // A stable id for a report, generated BEFORE the PDF is built, so the
  // same reference number can be printed on the watermark and then used
  // as the report's actual database id — the two always match exactly.
  function newReportId(){
    return (crypto.randomUUID ? crypto.randomUUID() : 'rpt-' + Date.now() + '-' + Math.random().toString(16).slice(2));
  }

  // Writes one permanent line to the audit log. Best-effort: a logging
  // failure should never block the actual action the user is trying to
  // do, so errors here are swallowed (and noted in the console only).
  async function logEvent(eventType, details){
    try{
      const profile = await currentProfile();
      await nexus.from('audit_log').insert({
        user_id: profile.id,
        user_name: profile.full_name || profile.email,
        event_type: eventType,
        details: details || {}
      });
    }catch(e){
      console.warn('Nexus audit log write failed (non-blocking):', e.message);
    }
  }

  // toolKey/sectionKey must match supabase/schema.sql values, e.g. 'event_sop' / 'customer_awareness'
  // Pass `id` (from newReportId()) if the same id was already printed on the PDF's watermark.
  async function saveReport({ id, toolKey, sectionKey, clientName, clientContact, summary, data, pdfBlob }){
    const profile = await currentProfile();
    const reportId = id || newReportId();
    let pdfPath = null;

    if (pdfBlob){
      pdfPath = `${profile.id}/${toolKey}/${Date.now()}.pdf`;
      const { error: upErr } = await nexus.storage.from('reports').upload(pdfPath, pdfBlob, {
        contentType: 'application/pdf'
      });
      if (upErr) throw upErr;
    }

    const { data: row, error } = await nexus.from('reports').insert({
      id: reportId,
      tool_key: toolKey,
      section_key: sectionKey,
      client_name: clientName || null,
      client_contact: clientContact || null,
      summary: summary || null,
      created_by: profile.id,
      created_by_name: profile.full_name || profile.email,
      data: data || {},
      pdf_path: pdfPath
    }).select().single();

    if (error) throw error;
    logEvent('report_saved', { toolKey, sectionKey, clientName: clientName || null, reportId });
    return row;
  }

  // Some tools' fancy report layout only exists inside a `@media print { }`
  // block (so it can differ from the on-screen editing view). html2canvas
  // renders using normal screen styles and ignores print media, so those
  // rules never apply during capture — producing an unstyled, misaligned
  // result. This temporarily lifts every print-only rule onto the page as
  // normal rules, runs `fn`, then removes them again.
  // Extracts every `@media print { ... }` rule from the live page's
  // stylesheets as plain CSS text (no @media wrapper), so it can be
  // applied outside of an actual print context.
  function extractPrintCss(){
    let css = '';
    for (const sheet of document.styleSheets){
      let rules;
      try{ rules = sheet.cssRules; } catch(e){ continue; } // cross-origin sheet, skip
      if (!rules) continue;
      for (const rule of rules){
        const isPrintMedia = rule.media && /print/i.test(rule.media.mediaText || '');
        if (isPrintMedia){
          for (const inner of rule.cssRules){ css += inner.cssText + '\n'; }
        }
      }
    }
    return css;
  }

  // Applies those rules to the LIVE page (so real DOM measurements, like
  // findSafeCutPoints' getBoundingClientRect calls, reflect print sizing
  // before anything is captured). Note: html2canvas builds its own
  // internal clone of whatever it's asked to render, and — a known
  // limitation — that internal clone doesn't reliably pick up styles
  // injected into <head> after the fact. That's why captureElementAsPdf
  // ALSO re-injects this same CSS text directly inside the element being
  // captured (see its `extraCss` handling below) — belt and suspenders,
  // covering both the live-DOM measurement step and the actual capture.
  async function withPrintStylesActive(fn){
    const styleEl = document.createElement('style');
    styleEl.textContent = extractPrintCss();
    document.head.appendChild(styleEl);
    try{
      return await fn();
    } finally {
      document.head.removeChild(styleEl);
    }
  }

  // Renders a DOM element to a canvas at 2x resolution for crisp text.
  //
  // html2canvas has a well-known gotcha: unless told the element's real
  // size, it defaults to capturing only one viewport's worth of height —
  // silently cutting off anything below that, regardless of how tall the
  // element actually is. Explicitly passing the element's own scrollWidth/
  // scrollHeight (both as the crop size AND as the "window" it renders
  // against) is the documented fix, and is what was missing before.
  async function renderToCanvas(el){
    return await html2canvas(el, {
      scale: CAPTURE_SCALE,
      useCORS: true,
      backgroundColor: '#ffffff',
      width: el.scrollWidth,
      height: el.scrollHeight,
      windowWidth: el.scrollWidth,
      windowHeight: el.scrollHeight
    });
  }

  // Finds Y coordinates (in CSS px, relative to rootEl's top) that sit
  // safely in the gap BETWEEN report sections — never through the middle
  // of one. Both Retirement Planner (.r-card) and CBA Tool (.rpt-card)
  // already tag their sections this way. Elements that overlap
  // vertically (e.g. two cards sitting side-by-side in a grid row) are
  // treated as one combined row, so a cut never lands mid-row even when
  // the two side-by-side cards are different heights.
  function findSafeCutPoints(rootEl){
    const cards = Array.from(rootEl.querySelectorAll('.r-card, .rpt-card'));
    if (!cards.length) return [];
    const rootRect = rootEl.getBoundingClientRect();
    const items = cards
      .map(el => {
        const r = el.getBoundingClientRect();
        return { top: r.top - rootRect.top, bottom: r.bottom - rootRect.top };
      })
      .filter(it => it.bottom > it.top)
      .sort((a, b) => a.top - b.top);

    const rows = [];
    items.forEach(it => {
      const last = rows[rows.length - 1];
      if (last && it.top < last.bottom - 2){
        last.bottom = Math.max(last.bottom, it.bottom);
        last.top = Math.min(last.top, it.top);
      } else {
        rows.push({ top: it.top, bottom: it.bottom });
      }
    });

    const cuts = [];
    for (let i = 0; i < rows.length - 1; i++){
      cuts.push((rows[i].bottom + rows[i + 1].top) / 2);
    }
    return cuts;
  }

  // Deep-clones an element for isolated, off-the-live-page capture — but
  // <canvas> elements don't carry their drawn pixels through cloneNode
  // (the clone comes back blank), so charts need their bitmap copied
  // over by hand after cloning.
  function cloneWithCanvases(el){
    const clone = el.cloneNode(true);
    const origCanvases = el.querySelectorAll('canvas');
    const cloneCanvases = clone.querySelectorAll('canvas');
    origCanvases.forEach((orig, i) => {
      const dest = cloneCanvases[i];
      if (!dest) return;
      dest.width = orig.width;
      dest.height = orig.height;
      const ctx = dest.getContext('2d');
      if (ctx) ctx.drawImage(orig, 0, 0);
    });
    return clone;
  }

  // Puts an element (or clone) into a full-width overlay that sits on top
  // of the page, captures it, then removes the overlay. Two things that
  // broke earlier versions of this and are fixed here:
  //  1) The overlay's height is left to grow with its content (no
  //     `bottom:0`/`inset:0` pinning it to one screen's height) — pinning
  //     it, combined with any overflow setting, silently cut off
  //     everything past the first screenful, which is what was happening
  //     to Table Performance's daily report.
  //  2) No `overflow` property is set at all, so nothing can clip it.
  async function captureInOverlay(node){
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;background:#fff;z-index:2147483647;display:flex;justify-content:center;padding:24px 0;';
    overlay.appendChild(node);
    document.body.appendChild(overlay);
    try{
      const cutPointsCss = findSafeCutPoints(node); // must run while attached (needs real layout)
      const canvas = await renderToCanvas(node);
      return { canvas, safeCutPointsPx: cutPointsCss.map(y => y * CAPTURE_SCALE) };
    } finally {
      document.body.removeChild(overlay);
    }
  }

  // Turns a canvas into a jsPDF blob, scaling the image to exactly fill
  // the PDF's page width (so it can never be cropped left/right) and
  // splitting across as many pages as the content needs.
  //
  // `safeCutPointsPx`, when available (see findSafeCutPoints above), are
  // real gaps between report sections, verified from the actual page
  // layout — cutting there is preferred whenever one exists within reach
  // of a page boundary. Only when none is available nearby does this
  // fall back to scanning the rendered pixels for a "quiet" (blank) row,
  // which is a good but imperfect guess at a safe gap.
  function canvasToPdfBlob(canvas, safeCutPointsPx){
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF({ unit: 'pt', format: 'a4', orientation: 'portrait' });
    const pageWidthPt = pdf.internal.pageSize.getWidth();
    const pageHeightPt = pdf.internal.pageSize.getHeight();

    const scale = pageWidthPt / canvas.width;      // canvas px -> pdf pt
    const pageHeightPx = pageHeightPt / scale;

    const ctx = canvas.getContext('2d');
    const sortedSafePoints = (safeCutPointsPx || []).slice().sort((a, b) => a - b);

    function isQuietRow(y){
      let data;
      try{ data = ctx.getImageData(0, y, canvas.width, 1).data; }
      catch(e){ return false; } // tainted canvas (shouldn't happen with useCORS) — just skip smart-cutting
      for (let x = 0; x < data.length; x += 4 * 6){ // sample every 6th pixel for speed
        if (!(data[x] > 232 && data[x+1] > 232 && data[x+2] > 232)) return false;
      }
      return true;
    }

    // Checks a whole vertical span (not just one row) is essentially
    // blank, by sampling a handful of rows spread across it.
    function isRegionBlank(yStart, yEnd){
      const span = yEnd - yStart;
      if (span <= 0) return true;
      const samples = Math.min(15, Math.max(3, Math.floor(span / 20)));
      const step = span / samples;
      for (let i = 0; i <= samples; i++){
        const y = Math.min(yEnd - 1, Math.round(yStart + i * step));
        if (!isQuietRow(y)) return false;
      }
      return true;
    }

    // Searches up to `maxBackPx` above the naive cut line for a quiet row.
    function findQuietCutY(targetY, maxBackPx){
      const limit = Math.min(maxBackPx, targetY - 1);
      for (let back = 0; back <= limit; back += 2){
        const y = Math.round(targetY - back);
        if (isQuietRow(y)) return y;
      }
      return targetY; // nothing quiet found nearby — cut at the target anyway
    }

    // Picks the best cut point at or before `targetY` (and after
    // `floorY`): prefer the closest real section gap; only fall back to
    // pixel-scanning if none exists within a generous search window.
    function bestCutY(targetY, floorY){
      let bestSafe = null;
      for (const p of sortedSafePoints){
        if (p > floorY && p <= targetY) bestSafe = p; // keep the largest one that still fits
      }
      if (bestSafe !== null) return bestSafe;
      return findQuietCutY(targetY, 500);
    }

    // First pass: compute every page boundary without drawing anything yet.
    const boundaries = [0];
    let cursor = 0;
    while (cursor < canvas.height){
      let end = Math.min(cursor + pageHeightPx, canvas.height);
      if (end < canvas.height){
        end = bestCutY(end, cursor);
        if (end <= cursor) end = Math.min(cursor + pageHeightPx, canvas.height);
      }
      boundaries.push(end);
      cursor = end;
    }

    // A trailing page that's entirely blank (pure whitespace overflow —
    // margins, padding, rounding) shouldn't exist at all: drop it
    // outright rather than rendering an almost-empty extra page.
    while (
      boundaries.length > 2 &&
      isRegionBlank(boundaries[boundaries.length - 2], boundaries[boundaries.length - 1])
    ){
      boundaries.pop();
    }

    for (let i = 0; i < boundaries.length - 1; i++){
      const sliceStart = boundaries[i];
      const sliceEnd = boundaries[i + 1];
      const sliceHeight = Math.round(sliceEnd - sliceStart);

      const sliceCanvas = document.createElement('canvas');
      sliceCanvas.width = canvas.width;
      sliceCanvas.height = sliceHeight;
      const sctx = sliceCanvas.getContext('2d');
      sctx.fillStyle = '#ffffff';
      sctx.fillRect(0, 0, sliceCanvas.width, sliceCanvas.height);
      sctx.drawImage(canvas, 0, sliceStart, canvas.width, sliceHeight, 0, 0, canvas.width, sliceHeight);

      if (i > 0) pdf.addPage();
      const imgHeightPt = sliceHeight * scale;
      pdf.addImage(sliceCanvas.toDataURL('image/jpeg', 0.98), 'JPEG', 0, 0, pageWidthPt, imgHeightPt);
    }

    return pdf.output('blob');
  }

  function triggerDownload(blob, filename){
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename || 'omega-financial-report.pdf';
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  // A rich accountability line used on every report: who made it, on whose
  // behalf, how to reach the firm, and exactly when it was generated.
  function buildStampHtml(name, refId){
    if (!name && !refId) return '';
    return `
      <div style="font-size:10.5px;color:#8a94a0;margin-bottom:16px;padding-bottom:10px;border-bottom:1px dashed #dfd9c8;line-height:1.7;">
        ${name ? `Prepared by: <b style="color:#4d5c68;">${name}</b> &middot; ` : ''}
        Organisation: <b style="color:#4d5c68;">Omega Financial</b> &middot;
        Phone: 9019008100 &middot;
        Website: www.omegafinancial.co.in<br/>
        Generated: ${new Date().toLocaleString()}
        ${refId ? ` &middot; Ref: <span style="font-family:monospace;">${refId}</span>` : ''}
      </div>`;
  }

  // Wraps content in a faint, repeating, diagonal watermark of the Omega
  // Financial icon (no wordmark text — a text-on-text watermark landing
  // on top of report text was making both unreadable). Tiled as a CSS
  // background pattern rather than one big centered image, so it never
  // concentrates into a single dense blob that could obscure a specific
  // line of the report, however long or short that report turns out to be.
  function watermarkLayerCss(){
    return `position:absolute;inset:0;z-index:0;pointer-events:none;
      background-image:url(${NEXUS_LOGO_WATERMARK});
      background-repeat:repeat;
      background-size:130px 182px;
      opacity:0.05;
      transform:rotate(-18deg) scale(1.3);
      transform-origin:center;`;
  }

  function withLogoWatermark(innerHtml){
    // Watermark disabled for now — removed as a variable while sorting
    // out page-fit issues. The div wrapper is kept (harmless) so nothing
    // else needs to change; it just no longer paints anything visible.
    return `<div style="position:relative;">${innerHtml}</div>`;
  }

  // Wraps arbitrary HTML in the Omega letterhead, then returns a PDF Blob
  // (and optionally triggers a browser download). Pass `preparedBy` and
  // `refId` (from newReportId()) to stamp accountability info on every
  // page — who generated it and its permanent reference number, so a
  // report can always be traced back to the person who created it.
  async function exportBrandedPDF({ title, subtitle, bodyHtml, filename, download = true, preparedBy, refId }){
    const wrapper = document.createElement('div');
    wrapper.style.fontFamily = "'Inter', Arial, sans-serif";
    wrapper.style.color = '#10202F';
    wrapper.style.padding = '36px 40px';
    wrapper.style.width = '760px';
    wrapper.style.background = '#fff';
    wrapper.style.boxSizing = 'border-box';
    wrapper.style.overflowX = 'hidden';
    wrapper.innerHTML = withLogoWatermark(`
      <div style="display:flex;justify-content:space-between;align-items:flex-end;border-bottom:3px solid #D4AF37;padding-bottom:14px;margin-bottom:18px;">
        <div>
          <div style="font-size:22px;font-weight:800;color:#0E2A47;">Omega Financial</div>
          <div style="font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:#8a6d10;">we empower with conviction</div>
        </div>
        <div style="text-align:right;font-size:11px;color:#4d5c68;">
          Omega Financial ARN-85700<br/>
          9019008100 &middot; www.omegafinancial.co.in
        </div>
      </div>
      ${buildStampHtml(preparedBy, refId)}
      <h1 style="font-size:20px;color:#0E2A47;margin:0 0 4px 0;">${title || 'Report'}</h1>
      ${subtitle ? `<div style="font-size:13px;color:#4d5c68;margin-bottom:18px;">${subtitle}</div>` : ''}
      <div>${bodyHtml}</div>
      <div style="margin-top:30px;padding-top:14px;border-top:1px solid #dfd9c8;font-size:10px;color:#8a94a0;">
        This document is generated by Nexus, Omega Financial's internal tool suite, for the named client's records.
        Mutual fund investments are subject to market risks. Please read scheme documents carefully.
        ${refId ? ` Internal Reference ID: ${refId}.` : ''}
      </div>
    `);

    const { canvas, safeCutPointsPx } = await captureInOverlay(wrapper);
    const pdfBlob = canvasToPdfBlob(canvas, safeCutPointsPx);
    if (download) triggerDownload(pdfBlob, filename);
    return pdfBlob;
  }

  // For tools that already render their OWN fully-branded, print-ready report
  // element (e.g. Retirement Planner's ".report" div, CBA Tool's summary).
  // Captures that element exactly as-is into a PDF, with no extra letterhead.
  // The element must already be visible (display != none) with a real size —
  // callers are responsible for making it visible before calling this.
  //
  // Captures a CLONE placed in its own isolated overlay (see
  // captureInOverlay above) rather than the live element in place — this
  // avoids the original getting clipped or squeezed by whatever else is
  // going on around it on the page (sticky headers, other layout
  // containers, etc.), which was still causing edge-cropping for some
  // reports even after the page-width scaling fix.
  //
  // Pass `watermark: { name, refId }` to stamp a thin accountability
  // strip at the very top of the captured report, plus the big diagonal
  // logo watermark behind the whole thing.
  //
  // Pass `extraCss` (a plain CSS text string, e.g. from
  // NexusBridge.extractPrintCss()) to have it embedded directly inside
  // the captured element. This exists because html2canvas builds its
  // own internal clone for rendering, and that internal clone doesn't
  // reliably see styles injected into the page's <head> after the fact
  // — embedding the CSS as a child of the very node being captured
  // travels with it regardless of how html2canvas clones things
  // internally, which is what finally made a tool's own tight print
  // styling actually take effect in the captured PDF.
  async function captureElementAsPdf(el, filename, download = false, watermark, extraCss){
    const clone = cloneWithCanvases(el);
    clone.style.width = getComputedStyle(el).width;
    clone.style.maxWidth = clone.style.width;
    clone.style.margin = '0';
    // If any inner element (a wide table row, a long unbroken label) is
    // naturally wider than the width we just set, the browser lets it
    // silently overflow rather than wrap — and that overflow was being
    // measured as the capture's "real" width, stretching a narrower
    // photograph to fill the full PDF page and leaving the rest blank.
    // Clipping horizontal overflow here guarantees the capture width is
    // always exactly the width we asked for.
    clone.style.overflowX = 'hidden';

    // Build an outer shell holding the real clone. (The diagonal icon
    // watermark that used to sit behind it is disabled for now — removed
    // as a variable while sorting out page-fit issues.)
    const shell = document.createElement('div');
    shell.style.position = 'relative';
    shell.style.width = clone.style.width;

    if (extraCss){
      const styleTag = document.createElement('style');
      styleTag.textContent = extraCss;
      shell.appendChild(styleTag);
    }

    const contentLayer = document.createElement('div');
    contentLayer.style.position = 'relative';
    contentLayer.style.zIndex = '1';

    if (watermark && (watermark.name || watermark.refId)){
      const stamp = document.createElement('div');
      stamp.style.cssText = 'font-family:Inter,Arial,sans-serif;padding:8px 4px 10px;';
      stamp.innerHTML = buildStampHtml(watermark.name, watermark.refId);
      contentLayer.appendChild(stamp);
    }
    contentLayer.appendChild(clone);
    shell.appendChild(contentLayer);

    const { canvas, safeCutPointsPx } = await captureInOverlay(shell);
    const pdfBlob = canvasToPdfBlob(canvas, safeCutPointsPx);
    if (download) triggerDownload(pdfBlob, filename);
    return pdfBlob;
  }

  // Strips anything that can't be sent to Supabase as JSON (DOM nodes,
  // Chart.js instances, canvases, functions, circular references) so a
  // tool can safely pass its whole state object as `data` without crashing.
  // Keeps primitives, arrays, and plain objects; drops the rest.
  function toSafeJSON(value){
    try{
      return JSON.parse(JSON.stringify(value, (key, val) => {
        if (val instanceof HTMLElement) return undefined;
        if (val && typeof val === 'object' && (val.canvas || val.ctx || val._chart)) return undefined;
        if (typeof val === 'function') return undefined;
        return val;
      }));
    }catch(e){
      // Fell back for genuinely circular structures JSON.stringify's replacer can't catch alone
      const seen = new WeakSet();
      return JSON.parse(JSON.stringify(value, (key, val) => {
        if (val instanceof HTMLElement) return undefined;
        if (typeof val === 'function') return undefined;
        if (typeof val === 'object' && val !== null){
          if (seen.has(val)) return undefined;
          seen.add(val);
        }
        return val;
      }));
    }
  }

  return { saveReport, exportBrandedPDF, captureElementAsPdf, toSafeJSON, withPrintStylesActive, extractPrintCss, currentProfile, newReportId, logEvent, buildStampHtml, LOGO_WATERMARK: NEXUS_LOGO_WATERMARK };
})();

/* =========================================================
   Discourage bypassing Nexus's saved-report system via the browser's
   own print function (Ctrl/Cmd+P). This can't make printing technically
   impossible — a browser will never let a webpage fully disable its own
   print feature — but it blocks the common shortcut, redirects people
   back to the proper flow, and logs every attempt either way so there's
   an accountability trail regardless.
   ========================================================= */
document.addEventListener('keydown', function(e){
  const isPrintShortcut = (e.ctrlKey || e.metaKey) && (e.key === 'p' || e.key === 'P');
  if (!isPrintShortcut) return;
  e.preventDefault();
  nexusToast('Direct printing is disabled here. Use "Save to Nexus", then download the PDF from the Reports section.', 'err');
  NexusBridge.logEvent('print_shortcut_blocked', { page: location.pathname });
});
window.addEventListener('beforeprint', function(){
  NexusBridge.logEvent('print_attempt_detected', { page: location.pathname });
});
